    int commonFactors(int a, int b) {
        int min,i=1,count=0;
        if(a<b)
            min=a;
        else
            min=b;
        while(i<=min){
            if(a%i==0&&b%i==0)
                count++;
            i++;
        }
        return count;
    }
};

class Solution(object):
    def commonFactors(self, a, b):
        """
        :type a: int
        :type b: int
        :rtype: int
        """
        ans = 0
        for i in range(1, min(a, b) + 1):
            if a % i == 0 and b % i == 0:
                ans += 1
        return ans
